using System;using System.Linq;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class FinishWastelandSurface {
 static float Edge(Vector2 p,Vector2 a,Vector2 b){var d=b-a;return Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/Mathf.Max(.001f,d.sqrMagnitude)));}
 static float Cross(Vector2 a,Vector2 b)=>a.x*b.y-a.y*b.x;
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop play first");var l=RoadGunnerLevelAuthoring.Current;var triangles=new System.Collections.Generic.List<Vector2[]>();foreach(var f in l.decorationRoot.Find("00 · Routes and clear ground").GetComponentsInChildren<MeshFilter>()){if(f.GetComponent<Renderer>().sharedMaterial.name!="Track")continue;var v=f.sharedMesh.vertices.Select(p=>f.transform.TransformPoint(p)).Select(p=>new Vector2(p.x,p.z)).ToArray();var t=f.sharedMesh.triangles;for(int i=0;i<t.Length;i+=3)triangles.Add(new[]{v[t[i]],v[t[i+1]],v[t[i+2]]});}
 var mesh=l.ground.sharedMesh;var verts=mesh.vertices;var workshop=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>();var arena=Quaternion.Euler(0,45,0)*new Vector3(-82.5f,0,87.5f);for(int i=0;i<verts.Length;i++){var w=l.ground.transform.TransformPoint(verts[i]);var p=new Vector2(w.x,w.z);float d=999;foreach(var t in triangles){float a=Cross(t[1]-t[0],p-t[0]),b=Cross(t[2]-t[1],p-t[1]),c=Cross(t[0]-t[2],p-t[2]);if((a>=0&&b>=0&&c>=0)||(a<=0&&b<=0&&c<=0)){d=0;break;}d=Mathf.Min(d,Edge(p,t[0],t[1]),Edge(p,t[1],t[2]),Edge(p,t[2],t[0]));}float weight=Mathf.SmoothStep(0,1,Mathf.InverseLerp(7,16,d));float wd=Vector2.Distance(p,new Vector2(workshop.transform.position.x,workshop.transform.position.z));float ad=Vector2.Distance(p,new Vector2(arena.x,arena.z));weight*=Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,28,wd))*Mathf.SmoothStep(0,1,Mathf.InverseLerp(27,35,ad));verts[i].y*=weight;}
 mesh.vertices=verts;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);l.ground.GetComponent<MeshCollider>().sharedMesh=null;l.ground.GetComponent<MeshCollider>().sharedMesh=mesh;EditorUtility.CopySerialized(mesh,l.baselineTerrain);EditorUtility.SetDirty(l.baselineTerrain);
 string root="Assets/RoadGunner/Levels/WastelandRestored/Materials/";var track=AssetDatabase.LoadAssetAtPath<Material>(root+"Track.mat");track.SetTexture("_BaseMap",null);track.SetTexture("_MainTex",null);EditorUtility.SetDirty(track);var rock=AssetDatabase.LoadAssetAtPath<Material>(root+"RockLight.mat");foreach(var r in l.obstaclesRoot.GetComponentsInChildren<Renderer>()){if(!r.name.Contains("Cliff"))continue;var m=r.sharedMaterials;for(int i=0;i<m.Length;i++)if(m[i].name=="Sand")m[i]=rock;r.sharedMaterials=m;PrefabUtility.RecordPrefabInstancePropertyModifications(r);}
 RoadGunnerLevelAuthoring.Save(l);return "Road shoulders, arena and workshop leveled; shallow dunes retained outside routes; navigation rebaked.";}
}
